<?php
$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT c.*,j.title,j.department,j.location,j.work_mode,j.employment_type,j.salary FROM candidates c JOIN jobs j ON j.id=c.job_id WHERE c.id=?");$st->bind_param('i',$id);$st->execute();$c=stmt_one($st);if(!$c)die('Candidate not found.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$new=$_POST['status']??$c['status'];$note=trim($_POST['recruiter_note']??'');$u=db()->prepare("UPDATE candidates SET status=?,recruiter_note=? WHERE id=?");$u->bind_param('ssi',$new,$note,$id);$u->execute();$ev=db()->prepare("INSERT INTO candidate_events(candidate_id,event_text) VALUES(?,?)");$ev->bind_param('is',$id,$text);$text='Status changed to '.status_label($new);$ev->execute();header('Location:candidate.php?id='.$id);exit;}
$ev=db()->prepare("SELECT * FROM candidate_events WHERE candidate_id=? ORDER BY created_at DESC");$ev->bind_param('i',$id);$ev->execute();$events=stmt_rows($ev);$title='Candidate';require 'header.php';?>
<div class="candidate-head"><div><a class="back" href="candidates.php">← Candidates</a><span class="eyebrow">APPLICATION <?=e($c['application_no'])?></span><h1><?=e($c['first_name'].' '.$c['last_name'])?></h1><p><?=e($c['title'])?> · <?=e($c['email'])?></p></div><span class="status-pill <?=e($c['status'])?>"><?=e(status_label($c['status']))?></span></div>
<div class="candidate-grid"><section class="admin-panel detail-panel"><h2>Candidate profile</h2><div class="info-grid"><div><small>Email</small><b><?=e($c['email'])?></b></div><div><small>Phone</small><b><?=e($c['phone']?:'—')?></b></div><div><small>Location</small><b><?=e($c['location']?:'—')?></b></div><div><small>Experience</small><b><?=e($c['experience']?:'—')?></b></div><div><small>Notice</small><b><?=e($c['notice_period']?:'—')?></b></div><div><small>Links</small><b><?php if($c['linkedin']):?><a href="<?=e($c['linkedin'])?>" target="_blank">LinkedIn</a><?php endif;?> <?php if($c['portfolio']):?><a href="<?=e($c['portfolio'])?>" target="_blank">Portfolio</a><?php endif;?></b></div></div><h2>Cover letter</h2><p class="letter"><?=nl2br(e($c['cover_letter']))?></p><a class="outline-btn" href="../uploads/<?=e($c['resume_path'])?>" target="_blank">Open resume</a></section>
<aside class="side-stack"><form class="admin-panel" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><h2>Recruiting action</h2><label>Status<select name="status"><?php foreach(['new','screening','interview','offer','hired','rejected'] as $s):?><option value="<?=$s?>" <?=$c['status']===$s?'selected':''?>><?=e(status_label($s))?></option><?php endforeach;?></select></label><label>Recruiter note<textarea name="recruiter_note" rows="6"><?=e($c['recruiter_note'])?></textarea></label><button class="btn dark full">Save candidate</button></form><section class="admin-panel"><h2>Timeline</h2><?php foreach($events as $x):?><div class="mini-event"><b><?=e($x['event_text'])?></b><small><?=e(date('M j · g:i A',strtotime($x['created_at'])))?></small></div><?php endforeach;?></section></aside></div><?php require 'footer.php'; ?>